const pairs = $input.all().map(i => i.json);
const out = [];
async function req(opts) {
  if (typeof $helpers !== 'undefined' && $helpers.httpRequest) return await $helpers.httpRequest(opts);
  const r = await fetch(opts.url, { method: opts.method || 'GET', headers: { 'Content-Type': 'application/json' }, body: opts.body ? JSON.stringify(opts.body) : undefined });
  const t = await r.text();
  if (opts.json) { try { return JSON.parse(t); } catch (e) { return t; } }
  return t;
}
function parseCsv(text) {
  const rows = []; let row = [], field = '', inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c !== '\r') field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  if (!rows.length) return [];
  const head = rows[0].map(h => h.trim());
  return rows.slice(1).filter(r => r.length > 1 || (r.length === 1 && r[0] !== '')).map(r => { const o = {}; head.forEach((h, idx) => { o[h] = r[idx] !== undefined ? r[idx] : ''; }); return o; });
}
for (const p of pairs) {
  const base = String(p.gosom_base_url || '').replace(/\/$/, '');
  if (!base) throw new Error('gosom_base_url not configured in sf2_config');
  const keyword = [p.search, p.location].filter(Boolean).join(' ');
  const job = await req({ method: 'POST', url: base + '/api/v1/jobs', body: { name: 'sf2 ' + keyword, keywords: [keyword], lang: 'en', depth: 1, max_time: 600 }, json: true, timeout: 30000 });
  const id = job && (job.id || job.ID);
  if (!id) throw new Error('gosom job create failed for query: ' + keyword);
  const deadline = Date.now() + 660000;
  let status = '';
  while (Date.now() < deadline) {
    await new Promise(r => setTimeout(r, 10000));
    const j = await req({ method: 'GET', url: base + '/api/v1/jobs/' + id, json: true, timeout: 30000 });
    status = String((j && (j.Status || j.status)) || '').toLowerCase();
    if (status === 'ok' || status === 'failed') break;
  }
  if (status !== 'ok') throw new Error('gosom job did not complete (status=' + (status || 'timeout') + ') for query: ' + keyword);
  const csv = await req({ method: 'GET', url: base + '/api/v1/jobs/' + id + '/download', timeout: 60000 });
  const rows = parseCsv(String(csv));
  for (const row of rows) out.push({ json: Object.assign({}, row, { _query: keyword, _engine_version: p.engine_version || 'v1.19.1' }) });
}
return out;

const items = $input.all().map(i => i.json);
const out = [];
for (const r of items) {
  const placeId = String(r.place_id || '').trim();
  if (!placeId) continue;
  const rating = parseFloat(r.review_rating);
  const rc = parseInt(r.review_count, 10);
  const pub = {};
  for (const k of Object.keys(r)) if (k.charAt(0) !== '_') pub[k] = r[k];
  out.push({ json: {
    source: 'apify_maps',
    source_id: placeId,
    name: r.title || '',
    place_id: placeId,
    category: r.category || null,
    location: r.address || null,
    website: String(r.website || '').trim() || null,
    phone: String(r.phone || '').trim() || null,
    rating: Number.isFinite(rating) ? rating : null,
    review_count: Number.isFinite(rc) ? rc : null,
    raw: Object.assign({}, pub, {
      discovery_engine: 'gosom',
      engine_version: r._engine_version || 'v1.19.1',
      query: r._query || null,
      observed_at: new Date().toISOString()
    })
  } });
}
return out;

const p = $input.item.json || {};
const pairSet = $('When Executed by Another Workflow').all().map(i => String(i.json.search || '') + '|' + String(i.json.location || ''));
return { json: {
  source: 'apify_maps',
  source_id: p.placeId || null,
  name: p.title || '',
  place_id: p.placeId || null,
  category: p.categoryName || null,
  location: p.city || p.address || null,
  website: p.website || null,
  phone: p.phone || null,
  rating: (p.totalScore === undefined ? null : p.totalScore),
  review_count: (p.reviewsCount === undefined ? null : p.reviewsCount),
  raw: Object.assign({}, p, {
    discovery_engine: 'apify',
    engine_version: 'compass-crawler-google-places',
    query_set: pairSet,
    observed_at: new Date().toISOString()
  })
} };
